export const CV_HEAD_ORDER = ["contact", "summary", "experience", "education", "skills", "projects", "certs", "languages", "other"];

export const CV_HEAD_NORM = CV_HEAD_ORDER.map((id) => [id, CV_HEADS[id].map((h) => matchNorm(h))]);

export const CV_MILITARY_RE = /(military( status| service)?|exempt(ed)?|postponed|completed( the)? (military )?service|served in the army|الموقف من التجنيد|موقف التجنيد|الخدمة العسكرية|معاف|معافى|مؤجل|أدى الخدمة|أدّى الخدمة|اتم الخدمة|أتم الخدمة|تم تأدية|منتهي|مُنهى)/i;

// A line is a heading when it is short, has no sentence punctuation, and equals / starts with / fuzzily matches a lexicon entry.
// Bold or larger lines (from the PDF/DOCX reader) and ALL-CAPS lines lower the bar; a line carrying a date range is never a heading.
export function headingId(line?: any, meta: any = {}) {
  const raw = line.replace(CV_BULLET, "").replace(/[:：\-–—|]+$/, "").replace(/^[\[\(]|[\]\)]$/g, "").trim(); if (!raw || raw.length > 48) return null;
  const n = matchNorm(raw.replace(/&/g, " and ").replace(/\//g, " ")); const words = n.split(" ").filter(Boolean); if (!words.length || words.length > 6) return null;
  if (/[.،؛;!?]/.test(raw) || /\d{4}/.test(raw) && !/^(education|التعليم)/i.test(raw)) return null; if (/\d{3,}|@|www\./.test(raw)) return null;
  const emph = !!(meta.bold || meta.heading || (meta.size && meta.size >= 1.15) || (/^[A-Z][A-Z\s&\/\-]{3,}$/.test(raw)));
  let best = null, bestSim = 0;
  for (const [id, forms] of CV_HEAD_NORM) for (const f of forms) {
    if (n === f) return id;
    if (n.startsWith(f + " ") && words.length - f.split(" ").length <= 3) { if (bestSim < 0.9) { best = id; bestSim = 0.9; } continue; }
    if (words.length <= 3) { const sim = tokenSim(n, f); if (sim > bestSim) { best = id; bestSim = sim; } }
  }
  if (bestSim >= 0.9) return best; if (bestSim >= 0.8 && (emph || words.length <= 2)) return best; if (bestSim >= 0.85 && words.length <= 3) return best;
  return null;
}

