export const CV_MONTHS = { jan: 1, january: 1, feb: 2, february: 2, mar: 3, march: 3, apr: 4, april: 4, may: 5, jun: 6, june: 6, jul: 7, july: 7, aug: 8, august: 8, sep: 9, sept: 9, september: 9, oct: 10, october: 10, nov: 11, november: 11, dec: 12, december: 12,
  "يناير": 1, "فبراير": 2, "مارس": 3, "أبريل": 4, "ابريل": 4, "إبريل": 4, "مايو": 5, "يونيو": 6, "يونيه": 6, "يوليو": 7, "يوليه": 7, "أغسطس": 8, "اغسطس": 8, "سبتمبر": 9, "أكتوبر": 10, "اكتوبر": 10, "نوفمبر": 11, "ديسمبر": 12,
  "كانون الثاني": 1, "شباط": 2, "آذار": 3, "اذار": 3, "نيسان": 4, "أيار": 5, "ايار": 5, "حزيران": 6, "تموز": 7, "آب": 8, "أيلول": 9, "ايلول": 9, "تشرين الأول": 10, "تشرين الاول": 10, "تشرين الثاني": 11, "كانون الأول": 12, "كانون الاول": 12 };

export const CV_PRESENT = /^(present|current|currently|now|till now|to date|until now|up to now|ongoing|today|حتى الآن|حتى الان|الآن|الان|حاليًا|حاليا|حالياً|حتى تاريخه|إلى الآن|الى الان|لغاية الآن|مستمر|حتى اليوم)$/i;

export const MONTH_RE = "(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?|يناير|فبراير|مارس|أبريل|ابريل|إبريل|مايو|يونيو|يونيه|يوليو|يوليه|أغسطس|اغسطس|سبتمبر|أكتوبر|اكتوبر|نوفمبر|ديسمبر|كانون الثاني|شباط|آذار|اذار|نيسان|أيار|ايار|حزيران|تموز|آب|أيلول|ايلول|تشرين الأول|تشرين الاول|تشرين الثاني|كانون الأول|كانون الاول)";

export const DATE_TOKEN = `(?:${MONTH_RE}\\.?,?\\s*(?:19|20)\\d{2}|(?:19|20)\\d{2}\\s*[\\/\\-.]\\s*\\d{1,2}|\\d{1,2}\\s*[\\/\\-.]\\s*(?:19|20)\\d{2}|(?:19|20)\\d{2}|present|current(?:ly)?|now|till now|to date|until now|up to now|ongoing|today|حتى الآن|حتى الان|الآن|الان|حاليًا|حاليا|حالياً|حتى تاريخه|إلى الآن|الى الان|لغاية الآن|مستمر|حتى اليوم)`;

export const CV_RANGE_RE = new RegExp(`(${DATE_TOKEN})\\s*(?:[-–—~]+|to|إلى|الى|حتى|till|until|through|/)\\s*(${DATE_TOKEN})`, "gi");

export const CV_YEAR_RE = /(?:19|20)\d{2}/g;
 export const CV_RANGE_TEST = new RegExp(CV_RANGE_RE.source, "i");

export function parseDateToken(s?: any) {
  const t = String(s || "").trim().replace(/[.,]+$/, ""); if (!t) return null; if (CV_PRESENT.test(t)) return { present: true };
  const nowY = new Date().getFullYear(); const lower = t.toLowerCase(); let m;
  if ((m = new RegExp(`^(${MONTH_RE})\\.?,?\\s*((?:19|20)\\d{2})$`, "i").exec(lower))) return { y: +m[2], m: CV_MONTHS[m[1].replace(/\.$/, "")] || 1 };
  if ((m = /^((?:19|20)\d{2})\s*[\/\-.]\s*(\d{1,2})$/.exec(lower))) return { y: +m[1], m: Math.min(12, Math.max(1, +m[2])) };
  if ((m = /^(\d{1,2})\s*[\/\-.]\s*((?:19|20)\d{2})$/.exec(lower))) return { y: +m[2], m: Math.min(12, Math.max(1, +m[1])) };
  if ((m = /^((?:19|20)\d{2})$/.exec(lower))) { const y = +m[1]; if (y > nowY + 1) return null; return { y, m: 1, yearOnly: true }; }
  return null;
}

export const monthsBetween = (a?: any, b?: any) => { const now = new Date(); const ey = b.present ? now.getFullYear() : b.y, em = b.present ? now.getMonth() + 1 : b.m; return Math.max(1, (ey - a.y) * 12 + (em - a.m)); };

export function parseRange(str?: any) {
  CV_RANGE_RE.lastIndex = 0; const m = CV_RANGE_RE.exec(String(str || "")); if (!m) return null; const a = parseDateToken(m[1]), b = parseDateToken(m[2]); if (!a || !b || a.present) return null;
  const start: any = { y: a.y, m: a.m }; const end = b.present ? { present: true } : { y: b.y, m: b.m }; if (!b.present && (b.y < a.y || (b.y === a.y && b.m < a.m))) return null;
  return { start, end, present: !!b.present, months: monthsBetween(start, end), text: m[0], index: m.index };
}

export const fmtYM = (d?: any) => d.present ? "حتى الآن" : (d.yearOnly || !d.m ? String(d.y) : `${String(d.m).padStart(2, "0")}/${d.y}`);

// ---- dictionaries: tools, codes & standards, certifications, phrases, verbs ----
export const defTool = (name?: any, re?: any, cat?: any, discs?: any) => ({ name, re: new RegExp("(?<![A-Za-z0-9\\u0621-\\u064A])(?:" + re + ")(?![A-Za-z0-9\\u0621-\\u064A])", "i"), cat, discs });

